     2	import { flue, flueWorkerConfig } from "@flue/vite";
     3	import { defineConfig } from "vite";
     4	
     5	// Dummy keys for the local S3 endpoint the dev server serves at /cdn-cgi/local/r2/s3, which checks
     6	// presigned URLs against them. They protect nothing and are the same values .dev.vars.example
     7	// gives both Workers' R2 keys.
     8	const LOCAL_S3_CREDENTIALS = {
     9	  accessKeyId: "nagaralocalaccesskey",
    10	  secretAccessKey: "nagaralocalsecretkey",
    11	};
    12	
    13	type R2Binding = { binding: string; local_dev?: { experimental_s3_credentials: object } };
    14	
    15	// The API Worker's wrangler dev persists to the same folder, so both Workers see one D1 database
    16	// and one bucket. The local S3 credentials are added only when serving, so the built deploy config
    17	// never carries them.
    18	export default defineConfig(({ command }) => {
    19	  // flueWorkerConfig binds to the flue() instance created before it in the same evaluation.
    20	  const fluePlugins = flue();
    21	  const flueConfig = flueWorkerConfig();
    22	
    23	  return {
    24	    server: { port: 5173, strictPort: true },
    25	    plugins: [
    26	      fluePlugins,
    27	      cloudflare({
    28	        persistState: { path: "../.wrangler-state" },
    29	        config: (config) => {
    30	          flueConfig(config);
    31	
    32	          if (command !== "serve") {
    33	            return;
    34	          }
    35	
    36	          for (const bucket of (config as { r2_buckets?: R2Binding[] }).r2_buckets ?? []) {
    37	            bucket.local_dev = { experimental_s3_credentials: LOCAL_S3_CREDENTIALS };
    38	          }
    39	        },
    40	      }),
    41	    ],
    42	  };
