     9	type Route = {
    10	  method: string;
    11	  path: RegExp;
    12	  handle: (request: Request, env: Cloudflare.Env, params: string[]) => Promise<Response>;
    13	};
    14	
    15	const ROUTES: Route[] = [
    16	  { method: "POST", path: /^\/items$/, handle: enqueue },
    17	  { method: "GET", path: /^\/items\/([^/]+)$/, handle: (_, env, [id]) => poll(env, id) },
    18	  { method: "POST", path: /^\/items\/([^/]+)\/retry$/, handle: (_, env, [id]) => retry(env, id) },
    19	  { method: "GET", path: /^\/items\/([^/]+)\/audio$/, handle: (_, env, [id]) => audio(env, id) },
    20	  {
    21	    method: "GET",
    22	    path: /^\/items\/([^/]+)\/images\/([^/]+)$/,
    23	    handle: (_, env, [id, hash]) => images(env, id, hash),
    24	  },
    25	];
    26	
    27	export default {
    28	  async fetch(request: Request, env: Cloudflare.Env): Promise<Response> {
    29	    const path = new URL(request.url).pathname;
    30	
    31	    if (path === "/health") {
    32	      return new Response("ok");
    33	    }
    34	
    35	    if (!hasValidKey(request, env)) {
    36	      return detail("invalid or missing X-API-Key", 401);
    37	    }
    38	
    39	    for (const { method, path: pattern, handle } of ROUTES) {
    40	      const match = request.method === method ? path.match(pattern) : null;
    41	
    42	      if (match != null) {
    43	        return await handle(request, env, match.slice(1));
    44	      }
    45	    }
    46	
    47	    return detail("not found", 404);
    48	  },
    49	} satisfies ExportedHandler<Cloudflare.Env>;
