     1	import { NonRetryableError } from "cloudflare:workflows";
     2	import { database, recordFetch, STEP } from "@nagara/common";
     3	import { scrape } from "../../firecrawl/client.ts";
     4	import { domainFromUrl } from "../../recipes/store.ts";
     5	import { requireItem } from "../require-item.ts";
     6	import { runStep, type StepContext } from "../wrapper.ts";
     7	
     8	// The HTML rides as this step's result, which a step caps near 1 MiB. The cap is checked against
     9	// the result as it is serialized, escaping included, so a page that would not fit fails here with
    10	// its own error instead of failing the Workflow when the result is stored.
    11	export const fetchStep = (ctx: StepContext) =>
    12	  runStep(ctx, STEP.fetch, "queued", "2 minutes", async () => {
    13	    const { env, itemId, instanceId } = ctx;
    14	    const db = database(env.DB);
    15	    const item = await requireItem(db, itemId);
    16	    const page = await scrape(env.FIRECRAWL_API_KEY, item.url);
    17	    const domain = domainFromUrl(page.finalUrl);
    18	
    19	    // The credit is spent the moment the scrape returns, so it is recorded even when the page
    20	    // turns out to be empty.
    21	    await recordFetch(
    22	      db,
    23	      itemId,
    24	      { workflow_instance_id: instanceId, extraction_domain: domain },
    25	      {
    26	        type: "firecrawl",
    27	        quantity: page.creditsUsed,
    28	        unit: "credits",
    29	        dollars: page.creditsUsed * env.firecrawlDollarsPerCredit,
    30	        detail: { destination: page.finalUrl, proxy: page.proxy },
    31	      },
    32	    );
    33	
    34	    if (page.html == null) {
    35	      throw new Error("firecrawl returned no HTML");
    36	    }
    37	
    38	    const result = { html: page.html, domain };
    39	    const size = new TextEncoder().encode(JSON.stringify(result)).byteLength;
    40	
    41	    if (size > env.maxHtmlBytes) {
    42	      throw new NonRetryableError(
    43	        `the fetched page serializes to ${size} bytes, over the ${env.maxHtmlBytes}-byte cap`,
    44	      );
    45	    }
    46	
    47	    return result;
    48	  });
