     1	import { STEP } from "@nagara/common";
     2	import { domainQueueStub, LEASE_GRANTED } from "../../queue/domain-queue.ts";
     3	import { failStep, runStep, type StepContext } from "../wrapper.ts";
     4	
     5	const LEASE_WAITS = 3;
     6	
     7	// Copied out of the RPC result, which carries a disposer a step result cannot hold.
     8	const askForLease = async ({ env, instanceId }: StepContext, domain: string) => {
     9	  const { granted } = await domainQueueStub(env, domain).acquire(instanceId);
    10	
    11	  return { granted };
    12	};
    13	
    14	// The waits sit between steps and write nothing, so current_step reads lease throughout. A grant
    15	// can be lost to a deploy, so each wait that times out is followed by asking again.
    16	export const leaseStep = async (ctx: StepContext, domain: string) => {
    17	  const { granted } = await runStep(ctx, STEP.lease, "queued", "1 minute", () =>
    18	    askForLease(ctx, domain),
    19	  );
    20	
    21	  if (granted) {
    22	    return;
    23	  }
    24	
    25	  for (let wait = 1; wait <= LEASE_WAITS; wait += 1) {
    26	    try {
    27	      await ctx.step.waitForEvent(`lease wait ${wait}`, {
    28	        type: LEASE_GRANTED,
    29	        timeout: "5 minutes",
    30	      });
    31	
    32	      return;
    33	    } catch {
    34	      const recheck = await ctx.step.do(`lease recheck ${wait}`, () => askForLease(ctx, domain));
