    35	    }
    36	
    37	    const waiting = this.waiting();
    38	
    39	    if (lease == null && (waiting.length === 0 || waiting[0] === instanceId)) {
    40	      this.ctx.storage.kv.put(
    41	        "waiting",
    42	        waiting.filter((waiter) => waiter !== instanceId),
